// --- 2. SSLKEYLOGFILE — TLS pre-master secret dump ---

var SSLKeyLogFileExfilCases = []TestCase{
	// --- TRUE POSITIVES ---
	{
		ID:               "TP-SSLKEYLOG-001",
		Command:          "export SSLKEYLOGFILE=/tmp/keys.log",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Persistent export — every TLS-using child process leaks pre-master secrets.",
		Tags:             []string{"tp", "tls", "exfil", "critical"},
	},
	{
		ID:               "TP-SSLKEYLOG-002",
		Command:          "SSLKEYLOGFILE=/tmp/k.log curl https://api.github.com/user",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Inline assignment — single curl session keys to file, GH bearer token recoverable.",
		Tags:             []string{"tp", "tls", "curl"},
	},
	{
		ID:               "TP-SSLKEYLOG-003",
		Command:          "SSLKEYLOGFILE=/dev/shm/k.log python3 fetch.py",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Python urllib3 honors SSLKEYLOGFILE; /dev/shm is volatile but readable by any process.",
		Tags:             []string{"tp", "tls", "python"},
	},
	{
		ID:               "TP-SSLKEYLOG-004",
		Command:          "env SSLKEYLOGFILE=/tmp/k.log node app.js",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "env wrapper — Node TLS module dumps session keys.",
		Tags:             []string{"tp", "tls", "node"},
	},
	{
		ID:               "TP-SSLKEYLOG-005",
		Command:          "export SSLKEYLOGFILE=/var/tmp/tls.keys",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Persistent export to /var/tmp — survives reboot on many systems.",
		Tags:             []string{"tp", "tls", "persistence"},
	},

	// --- TRUE NEGATIVES ---
	{
		ID:               "TN-SSLKEYLOG-001",
		Command:          "unset SSLKEYLOGFILE",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Defensive unset — explicitly DISABLES key logging, must not block.",
		Tags:             []string{"tn", "safe", "defensive"},
	},
	{
		ID:               "TN-SSLKEYLOG-002",
		Command:          `echo "$SSLKEYLOGFILE"`,
		ExpectedDecision: "ALLOW",
		Classification:   "TN",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Variable read (no =) — diagnostic check, not assignment.",
		Tags:             []string{"tn", "safe", "diagnostic"},
	},
	{
		ID:               "TN-SSLKEYLOG-003",
		Command:          "env | grep -v SSLKEYLOGFILE",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Filtering env output — never assigns the variable.",
		Tags:             []string{"tn", "safe"},
	},
	{
		ID:               "TN-SSLKEYLOG-004",
		Command:          `git commit -m "security: warn devs not to export SSLKEYLOGFILE in CI runners"`,
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "Commit message discussing the threat in prose — doc context.",
		Tags:             []string{"tn", "safe", "doc-context"},
	},
	{
		ID:               "TN-SSLKEYLOG-005",
		Command:          `gh issue create --title "FP candidate" --body "we should detect SSLKEYLOGFILE=/tmp/x assignments from agents"`,
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "credential-exposure/cryptographic-keys/tls-keylog-exfil",
		Analyzer:         "regex",
		Description:      "gh issue body referencing the assignment in prose — doc context.",
		Tags:             []string{"tn", "safe", "doc-context"},
	},
}

